<?php
namespace App\Models; use App\Models\Concerns\BelongsToBusiness; use Illuminate\Database\Eloquent\Model;
class JournalEntry extends Model {use BelongsToBusiness;protected $fillable=['business_id','entry_number','entry_date','description','source_type','source_id','status','reversal_of_id','reason','is_recurring','recurrence','next_run_at','created_by','approved_by','reversed_by','approved_at','reversed_at'];protected $casts=['entry_date'=>'date','next_run_at'=>'date','approved_at'=>'datetime','reversed_at'=>'datetime','is_recurring'=>'boolean'];public function lines(){return $this->hasMany(JournalLine::class);}public function reversalOf(){return $this->belongsTo(self::class,'reversal_of_id');}public function getTotalDebitAttribute(){return (float)$this->lines->sum('debit');}public function getTotalCreditAttribute(){return (float)$this->lines->sum('credit');}}
